def validate_transfer(account, recipient, amount_cents: int) -> str | None:
    if account is None or not account.is_open:
        return "closed_account"
    if recipient is None or account.id == recipient.id:
        return "invalid_recipient"
    if amount_cents <= 0:
        return "non_positive_amount"
    if amount_cents > account.available_cents:
        return "insufficient_funds"
    return None

