export async function fetchManifest(url, signal) {
  try {
    const resp = await fetch(url, { signal });
    return await resp.json();
  } catch (err) {
    if (err && err.name === "AbortError") {
      return null;
    }
    throw err;
  }
}

export function parsePort(raw: unknown): number {
